def extract_exec_path(line):
    """Parse a line of strace output and returns the file being executed."""
    line = strip_pid_prefix(line)
    for method in exec_methods:
        prefix = method + '("'
        if line.startswith(prefix):
            line = line[len(prefix):]
            parts = line.split('", ')
            if len(parts) > 1:
                return parts[0]
    return None

def extract_open_path(line):
    """Parse a line of strace output and returns the file being opened."""
    line = strip_pid_prefix(line)
    for prefix in ['openat(AT_FDCWD, "', 'open("']:
        if line.startswith(prefix):
            parts = line[len(prefix):].split('", ')
            if len(parts) != 2:
                continue
            if 'ENOENT' in parts[1]:
                continue
            if 'O_RDONLY' not in parts[1]:
                continue
            if 'O_DIRECTORY' in parts[1]:
                continue
            return parts[0]
    return None

def extract_stat_path(line):
    """Parse a line of strace output and return the file that stat was called on."""
    line = strip_pid_prefix(line)
    prefix = 'stat("'
    if line.startswith(prefix):
        parts = line[len(prefix):].split('", ')
        if len(parts) == 2 and 'ENOENT' not in parts[1]:
            return parts[0]
    return None

def extract_paths(content, existing_only=True):
    """Parses paths from a piped input.

    Args:
        content (str): The raw input, can be either a list of files,
            or the output of the strace command.
        existing_only (bool, optional): Requires that files actually exist and aren't directories.
    Returns:
        A list of paths.
    """
    lines = [line.strip() for line in content.splitlines() if len(line.strip())]
    if not len(lines):
        return lines

    # The strace output will start with the exec call of its argument.
    strace_mode = extract_exec_path(lines[0]) is not None
    if not strace_mode:
        return lines

    # Extract files from `open()`, `openat()`, and `exec()` calls.
    paths = set()
    for line in lines:
        path = extract_exec_path(line) or extract_open_path(line) or extract_stat_path(line)
        if path:
            blacklisted = any(path.startswith(directory) for directory in blacklisted_directories)
            if not blacklisted:
                if not existing_only:
                    paths.add(path)
                    continue
                if os.path.exists(path) and os.access(path, os.R_OK) and not os.path.isdir(path):
                    paths.add(path)

    return list(paths)

def strip_pid_prefix(line):
    """Strips out the `[pid XXX] ` prefix if present."""
    match = re.match(r'\[pid\s+\d+\]\s*', line)
    if match:
        return line[len(match.group()):]
    return line

def find_executable(binary_name, skip_original_for_testing=False):
    # This won't be set on Alpine Linux, but it's required for the `find_executable()` calls.
    if 'PATH' not in os.environ:
        os.environ['PATH'] = '/bin/:/usr/bin/'
    executable = find_executable_original(binary_name)
    if executable and not skip_original_for_testing:
        return executable
    # Try to find it within the same bundle if it's not actually in the PATH.
    directory = parent_directory
    while True:
        directory, basename = os.path.split(directory)
        if not len(basename):
            break
        # The bundle directory.
        if re.match('[A-Fa-f0-9]{64}', basename):
            for bin_directory in os.environ['PATH'].split(':'):
                if os.path.isabs(bin_directory):
                    bin_directory = os.path.relpath(bin_directory, '/')
                candidate_executable = os.path.join(directory, basename,
                                                    bin_directory, binary_name)
                if os.path.exists(candidate_executable):
                    return candidate_executable

def compile(code):
    try:
        return compile_musl(code)
    except CompilerNotFoundError:
        try:
            return compile_diet(code)
        except CompilerNotFoundError:
            raise CompilerNotFoundError('No suiteable C compiler was found.')

def compile_diet(code):
    diet = find_executable('diet')
    gcc = find_executable('gcc')
    if diet is None or gcc is None:
        raise CompilerNotFoundError('The diet compiler was not found.')
    return compile_helper(code, [diet, 'gcc'])

def compile_musl(code):
    musl = find_executable('musl-gcc')
    if musl is None:
        raise CompilerNotFoundError('The musl compiler was not found.')
    return compile_helper(code, [musl])

def construct_bash_launcher(linker, library_path, executable, full_linker=True):
    linker_dirname, linker_basename = os.path.split(linker)
    full_linker = 'true' if full_linker else 'false'
    return render_template_file('launcher.sh', linker_basename=linker_basename,
                                linker_dirname=linker_dirname, library_path=library_path,
                                executable=executable, full_linker=full_linker)

def render_template(string, **context):
    for key, value in context.items():
        string = string.replace('{{%s}}' % key, value)
    return string

def render_template_file(filename, **context):
    if not os.path.isabs(filename):
        filename = os.path.join(template_directory, filename)
    with open(filename, 'r') as f:
        return render_template(f.read(), **context)

def configure_logging(quiet, verbose, suppress_stdout=False):
    # Set the level.
    from exodus_bundler import root_logger
    log_level = logging.WARN
    if quiet and not verbose:
        log_level = logging.ERROR
    elif verbose and not quiet:
        log_level = logging.INFO
    root_logger.setLevel(log_level)

    class StderrFilter(logging.Filter):
        def filter(self, record):
            return record.levelno in (logging.WARN, logging.ERROR)

    stderr_handler = logging.StreamHandler(sys.stderr)
    stderr_formatter = logging.Formatter('%(levelname)s: %(message)s')
    stderr_handler.setFormatter(stderr_formatter)
    stderr_handler.addFilter(StderrFilter())
    root_logger.addHandler(stderr_handler)

    # We won't even configure/add the stdout handler if this is specified.
    if suppress_stdout:
        return

    class StdoutFilter(logging.Filter):
        def filter(self, record):
            return record.levelno in (logging.DEBUG, logging.INFO)

    stdout_formatter = logging.Formatter('%(message)s')
    stdout_handler = logging.StreamHandler(sys.stdout)
    stdout_handler.setFormatter(stdout_formatter)
    stdout_handler.addFilter(StdoutFilter())
    root_logger.addHandler(stdout_handler)

def main(args=None, namespace=None):
    args = parse_args(args, namespace)

    # Dynamically set the default output to stdout if it is being piped.
    if args['output'] is None:
        if sys.stdout.isatty():
            args['output'] = './exodus-{{executables}}-bundle.{{extension}}'
        else:
            args['output'] = '-'

    # Handle the CLI specific options here, removing them from `args` in the process.
    quiet, verbose = args.pop('quiet'), args.pop('verbose')
    suppress_stdout = args['output'] == '-'
    configure_logging(quiet=quiet, verbose=verbose, suppress_stdout=suppress_stdout)

    # Allow piping in additional files.
    if not sys.stdin.isatty():
        args['add'] += extract_paths(sys.stdin.read())

    # Create the bundle with all of the arguments.
    try:
        create_bundle(**args)
    except FatalError as fatal_error:
        logger.error('Fatal error encountered, exiting.')
        logger.error(fatal_error, exc_info=verbose)
        sys.exit(1)

def bytes_to_int(bytes, byteorder='big'):
    """Simple helper function to convert byte strings into integers."""
    endian = {'big': '>', 'little': '<'}[byteorder]
    chars = struct.unpack(endian + ('B' * len(bytes)), bytes)
    if byteorder == 'big':
        chars = chars[::-1]
    return sum(int(char) * 256 ** i for (i, char) in enumerate(chars))

def resolve_file_path(path, search_environment_path=False):
    """Attempts to find a normalized path to a file.

    If the file is not found, or if it is a directory, appropriate exceptions will be thrown.

    Args:
        path (str): Either a relative or absolute path to a file, or the name of an
            executable if `search_environment_path` is `True`.
        search_environment_path (bool): Whether PATH should be used to resolve the file.
    """
    if search_environment_path:
        path = resolve_binary(path)
    if not os.path.exists(path):
        raise MissingFileError('The "%s" file was not found.' % path)
    if os.path.isdir(path):
        raise UnexpectedDirectoryError('"%s" is a directory, not a file.' % path)
    return os.path.normpath(os.path.abspath(path))

def destination(self):
    """str: The relative path for the destination of the actual file contents."""
    return os.path.join('.', 'data', self.hash)

def elf(self):
    """bool: Determines whether a file is a file is an ELF binary."""
    return detect_elf_binary(self.path)

def requires_launcher(self):
    """bool: Whether a launcher is necessary for this file."""
    # This is unfortunately a heuristic approach because many executables are compiled
    # as shared libraries, and many mostly-libraries are executable (*e.g.* glibc).

    # The easy ones.
    if self.library or not self.elf or not self.elf.linker_file or not self.executable:
        return False
    if self.elf.type == 'executable':
        return True
    if self.entry_point:
        return True

    # These will hopefully do more good than harm.
    bin_directories = ['/bin/', '/bin32/', '/bin64/']
    lib_directories = ['/lib/', '/lib32/', '/lib64/']
    in_bin_directory = any(directory in self.path for directory in bin_directories)
    in_lib_directory = any(directory in self.path for directory in lib_directories)
    if in_bin_directory and not in_lib_directory:
        return True
    if in_lib_directory and not in_bin_directory:
        return False

    # Most libraries will include `.so` in the filename.
    return re.search(r'\.so(?:\.|$)', self.path)

def source(self):
    """str: The relative path for the source of the actual file contents."""
    return os.path.relpath(self.path, '/')

def resolve_binary(binary):
    """Attempts to find the absolute path to the binary."""
    absolute_binary_path = os.path.normpath(os.path.abspath(binary))
    if not os.path.exists(absolute_binary_path):
        for path in os.getenv('PATH', '/bin/:/usr/bin/').split(os.pathsep):
            absolute_binary_path = os.path.normpath(os.path.abspath(os.path.join(path, binary)))
            if os.path.exists(absolute_binary_path):
                break
        else:
            raise MissingFileError('The "%s" binary could not be found in $PATH.' % binary)
    return absolute_binary_path

def run_ldd(ldd, binary):
    """Runs `ldd` and gets the combined stdout/stderr output as a list of lines."""
    if not detect_elf_binary(resolve_binary(binary)):
        raise InvalidElfBinaryError('The "%s" file is not a binary ELF file.' % binary)

    process = Popen([ldd, binary], stdout=PIPE, stderr=PIPE)
    stdout, stderr = process.communicate()
    return stdout.decode('utf-8').split('\n') + stderr.decode('utf-8').split('\n')

def parse_dependencies_from_ldd_output(content):
    """Takes the output of `ldd` as a string or list of lines and parses the dependencies."""
    if type(content) == str:
        content = content.split('\n')

    dependencies = []
    for line in content:
        # This first one is a special case of invoking the linker as `ldd`.
        if re.search(r'^\s*(/.*?)\s*=>\s*ldd\s*\(', line):
            # We'll exclude this because it's the hardcoded INTERP path, and it would be
            # impossible to get the full path from this command output.
            continue
        match = re.search(r'=>\s*(/.*?)\s*\(', line)
        match = match or re.search(r'\s*(/.*?)\s*\(', line)
        if match:
            dependencies.append(match.group(1))

    return dependencies

def dependencies(self):
    """Run's the files' linker iteratively and returns a set of all library dependencies."""
    all_dependencies = set()
    unprocessed_dependencies = set(self.direct_dependencies)
    while len(unprocessed_dependencies):
        all_dependencies |= unprocessed_dependencies
        new_dependencies = set()
        for dependency in unprocessed_dependencies:
            if dependency.elf:
                new_dependencies |= set(
                    dependency.elf.find_direct_dependencies(self.linker_file))
        unprocessed_dependencies = new_dependencies - all_dependencies
    return all_dependencies

def direct_dependencies(self):
    """Runs the file's linker and returns a set of the dependencies as `File` instances."""
    return self.find_direct_dependencies()

def find_dependencies(self, path):
    """Finds a list of all of the files contained with the package containing a file."""
    owner = self.find_owner(path)
    if not owner:
        return None

    args = self.list_command + [owner]
    process = subprocess.Popen(args, stdout=subprocess.PIPE)
    stdout, stderr = process.communicate()
    dependencies = []
    for line in stdout.decode('utf-8').split('\n'):
        match = re.search(self.list_regex, line.strip())
        if match:
            dependency_path = match.groups()[0]
            if os.path.exists(dependency_path) and not os.path.isdir(dependency_path):
                dependencies.append(dependency_path)

    return dependencies

def find_owner(self, path):
    """Finds the package that owns the specified file path."""
    if not self.cache_exists or not self.commands_exist:
        return None
    args = self.owner_command + [path]
    env = os.environ.copy()
    env['LC_ALL'] = 'C'
    process = subprocess.Popen(args, stdout=subprocess.PIPE, env=env)
    stdout, stderr = process.communicate()
    output = stdout.decode('utf-8').strip()
    match = re.search(self.owner_regex, output)
    if match:
        return match.groups()[0].strip()

def cache_exists(self):
    """Whether or not the expected package cache directory exists."""
    return os.path.exists(self.cache_directory) and os.path.isdir(self.cache_directory)

def commands_exist(self):
    """Whether or not the list and owner package manager commands can be resolved."""
    commands = {self.list_command[0], self.owner_command[0]}
    return all(find_executable(command) is not None for command in commands)

def detect_dependencies(path):
    # We'll go through the supported systems one by one.
    for package_manager in package_managers:
        dependencies = package_manager.find_dependencies(path)
        if dependencies:
            return dependencies

    return None

def __init__(self, function):
    self.__doc__ = getattr(function, '__doc__')
    self.function = function

def __hash__(self):
    """Defines a hash for the object so it can be used in sets."""
    return hash(self.path)

def __get__(self, instance, type):
    result = instance.__dict__[self.function.__name__] = self.function(instance)
    return result

def bundle_root(self):
    """str: The root directory of the bundle where the original file structure is mirrored."""
    path = os.path.join(self.working_directory, 'bundles', self.hash)
    return os.path.normpath(os.path.abspath(path))

def hash(self):
    """str: Computes a hash based on the current contents of the bundle."""
    file_hashes = sorted(file.hash for file in self.files)
    combined_hashes = '\n'.join(file_hashes).encode('utf-8')
    return hashlib.sha256(combined_hashes).hexdigest()

def __eq__(self, other):
    return isinstance(other, File) and self.path == self.path and \
        self.entry_point == self.entry_point

def __hash__(self):
    """Computes a hash for the instance unique up to the file path and entry point."""
    return hash((self.path, self.entry_point))

def hash(self):
    """str: Computes a hash based on the file content, useful for file deduplication."""
    with open(self.path, 'rb') as f:
        return hashlib.sha256(f.read()).hexdigest()
